## Why This Is Asked
Tests practical understanding of AWS-native backup primitives, SAP data protection strategies, automation implementation, and failure alerting mechanisms at a foundational level. This question evaluates end-to-end data flow design beyond basic backup procedures.

## Key Concepts
- AWS Backup service for SAP HANA data protection
- S3 versioning for backup retention and recovery
- SSM Document integration for remote command execution
- SAP HANA backup verification commands and validation
- SNS alerting and IAM permission management
- Lambda-based automation and error handling

## Code Example
```javascript
const AWS = require('aws-sdk');
const ssm = new AWS.SSM();
const s3 = new AWS.S3();
const sns = new AWS.SNS();

exports.handler = async (event) => {
  try {
    const params = {
      DocumentName: 'SAP-HANA-Backup-Verify',
      InstanceIds: [process.env.HANA_INSTANCE_ID],
      Parameters: {
        'backupPath': [event.backupPath]
      }
    };

    const command = await ssm.sendCommand(params).promise();

    // Wait for command completion and get results
    const result = await ssm.waitFor('commandExecuted', {
      CommandId: command.Command.CommandId,
      InstanceId: process.env.HANA_INSTANCE_ID
    }).promise();

    const report = {
      timestamp: new Date().toISOString(),
      backupPath: event.backupPath,
      status: result.Status,
      output: result.StandardOutputContent
    };

    await s3.putObject({
      Bucket: process.env.REPORT_BUCKET,
      Key: `backup-reports/${report.timestamp}.json`,
      Body: JSON.stringify(report, null, 2)
    }).promise();

    if (result.Status !== 'Success') {
      await sns.publish({
        TopicArn: process.env.ALERT_TOPIC,
        Subject: 'SAP HANA Backup Verification Failed',
        Message: JSON.stringify(report)
      }).promise();
    }

    return report;
  } catch (error) {
    console.error('Backup verification failed:', error);
    throw error;
  }
};
```

## Why This Is Asked
Tests knowledge of AWS patching automation, SAP patching options, health checks, rollback strategies, and CloudFormation for operational guardrails.

## Key Concepts
- AWS Systems Manager Maintenance Windows
- SAP patching options: SUM vs OS patches
- Pre/post patch validation: SAPControl, SAP background jobs, host metrics
- Rollback strategies: SAP backups, AMI snapshots
- CloudFormation for roles and patch baselines

## Code Example
```javascript
// CFN skeleton (pseudo)
{
  "AWSTemplateFormatVersion": "2010-09-09",
  "Resources": {
    "SAPSSMRole": {
      "Type": "AWS::IAM::Role",
      "Properties": {
        "AssumeRolePolicyDocument": { "Version": "2012-10-17", "Statement": [ { "Effect": "Allow", "Principal": { "Service": ["ec2.amazonaws.com", "ssm.amazonaws.com"] }, "Action": "sts:AssumeRole" } ] },
        "ManagedPolicyArns": [ "arn:aws:iam::aws:policy/AmazonSSMFullAccess" ]
      }
    },
    "SAPPatchBaseline": {
      "Type": "AWS::SSM::PatchBaseline",
      "Properties": {
        "Name": "SAPBaseline",
        "OperatingSystem": "AmazonLinux2"
      }
    }
  }
}
```

## Follow-up Questions

- How would you verify patch success in SAP and the OS without impacting production?
- How would you extend to multi-region DR alignment and scoped approvals?

## Why This Is Asked
This question tests the ability to orchestrate cross-account patch management for SAP workloads, combining OS and SAP-level patching with governance controls and rollback capabilities.

## Key Concepts
- AWS Systems Manager Patch Manager for OS-level patches
- SAP Maintenance Planner and SAP SUM for kernel and application patches
- Jira/ServiceNow integration for approval workflows and audit trails
- Rollback strategies with validated database and system backups
- Cross-account logging and monitoring via CloudWatch and S3
- IAM roles configured with least privilege principles across accounts

## Code Example
```javascript
// Step Functions skeleton (patch workflow)
{
  "Comment": "Cross-account SAP patch management workflow",
  "StartAt": "PreFlightChecks",
  "States": {
    "PreFlightChecks": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:preFlightChecks",
      "Next": "ApprovalGate"
    },
    "ApprovalGate": {
      "Type": "WaitForApproval",
      "Next": "PauseSAPServices"
    },
    "PauseSAPServices": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:pauseSAP",
      "Next": "OSPatch"
    },
    "OSPatch": {
      "Type": "Task",
      "Resource": "aws:ssm:executePatchBaseline",
      "Next": "SAPKernelPatch"
    },
    "SAPKernelPatch": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:runSUM",
      "Next": "SAPAppPatch"
    },
    "SAPAppPatch": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:runSUMApp",
      "Next": "ValidateHealth"
    },
    "ValidateHealth": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:healthCheck",
      "Next": "DecisionChoice"
    },
    "DecisionChoice": {
      "Type": "Choice",
      "Choices": [{
        "Variable": "$.healthStatus",
        "StringEquals": "healthy",
        "Next": "ResumeServices"
      }],
      "Default": "Rollback"
    },
    "ResumeServices": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:resumeSAP",
      "Next": "AuditLog"
    },
    "Rollback": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:rollback",
      "Next": "AuditLog"
    },
    "AuditLog": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:region:account:function:auditLog",
      "End": true
    }
  }
}
```

```hcl
# IaC snippet - Patch Baseline
resource "aws_ssm_patch_baseline" "sap_patch_baseline" {
  name             = "SAP-OS-Patch-Baseline"
  description      = "Patch baseline for SAP on EC2"
  operating_system = "SUSE"

  approval_rules {
    patch_filter {
      key    = "PRODUCT"
      values = ["SUSE_SLES_SAP_12", "SUSE_SLES_SAP_15"]
    }
    compliance_level = "CRITICAL"
    approve_after_days = 7
  }

  approved_patches_enabled = true
  approved_patches         = ["*"]
}
